"entrada":["guion","copy_video"],"salida_artefacto":"pedido_video","tope_usd":0,"vuelve_a":{"paso":"mesa","max":1,"si":{"tipo":"si_artefacto","artefacto":"pedido_video","campo":"vuelve_a_la_mesa","igual":true}}},{"clave":"video","tipo":"codigo","quien":"sala","funcion":"video","condicion":{"tipo":"siempre"},"entrada":["pedido_video"],"salida_artefacto":"video","tope_usd":0,"tope_usd_por_segundo":1},{"clave":"cuadros_video","tipo":"codigo","quien":"sala","funcion":"cuadros_video","condicion":{"tipo":"siempre"},"entrada":["video","guion"],"salida_artefacto":"cuadros_video","tope_usd":0},{"clave":"mirar_video","tipo":"agente","quien":"marketing_video_optimization_specialist","condicion":{"tipo":"si_artefacto","artefacto":"cuadros_video","campo":"hay_cuadros","igual":true},"entrada":["cuadros_video","guion"],"salida_artefacto":"mirada_video","tope_usd":0.5,"salida":{"esquema":"mirada_video.v1","reintento_formato":1},"vuelve_a":{"paso":"mesa","max":1,"si":{"tipo":"si_artefacto","artefacto":"mirada_video","campo":"vuelve_a_la_mesa","igual":true}}},{"clave":"chequeos","tipo":"codigo","quien":"sala","funcion":"chequeos_video","condicion":{"tipo":"siempre"},"entrada":["video","copy_video","pedido_video"],"salida_artefacto":"chequeos","tope_usd":0},{"clave":"jefatura","tipo":"jefatura","quien":"jefatura","condicion":{"tipo":"siempre"},"entrada":["guion","copy_video","video","chequeos"],"salida_artefacto":"respuesta_imagen","tope_usd":0},{"clave":"chequeos_2","tipo":"codigo","quien":"sala","funcion":"chequeos_video","condicion":{"tipo":"si_cambio","artefacto":"copy_video"},"entrada":["video","copy_video","pedido_video"],"salida_artefacto":"chequeos","tope_usd":0},{"clave":"entrega","tipo":"codigo","quien":"sala","funcion":"empaquetar_entrega_video","condicion":{"tipo":"siempre"},"entrada":["copy_video","video","chequeos","guion"],"salida_artefacto":"entrega","tope_usd":0},{"clave":"cierre","tipo":"codigo","quien":"sala","funcion":"cierre","condicion":{"tipo":"siempre"},"entrad