    RAISE EXCEPTION '202611171900: los pasos de video_mesa no son los esperados; no se pisan';
  END IF;
  IF (SELECT limites FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM $lim_antes${"margen":50,"tope_encargo_usd":43,"max_rondas":2,"imagenes_generadas_max":0,"reuso_dias":14,"plataforma":"instagram-reel","pie_de_foto_max":2200,"hashtags_max":30,"limites_verificados":false,"formato_por_omision":"9:16","mesa":true,"video":{"resolucion":"720p","segundos_min":8,"segundos_max":15,"plano_por_plano":true,"propuestas":3,"borrador":{"resolucion":"480p"}},"reserva_por_pieza_usd":30,"imagen_clave":{"borrador":{"quality":"low","size":"1024x1536"},"final":{"quality":"max","size":"1024x1536"}},"tope_encargo_usd_por_segundo":1}$lim_antes$::jsonb THEN
    RAISE EXCEPTION '202611171900: los límites de video_mesa no son los esperados; no se pisan';
  END IF;
  IF (SELECT tope_encargo_usd FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM 58::numeric THEN
    RAISE EXCEPTION '202611171900: el tope del encargo de video_mesa no es el esperado (58); no se pisa';
  END IF;
  IF (SELECT valor FROM public.cadena_config WHERE clave = 'brazo_de_video') IS DISTINCT FROM $brazo_antes${"tope_por_video_usd":15}$brazo_antes$::jsonb THEN
    RAISE EXCEPTION '202611171900: la configuración del brazo de video no es la esperada; no se pisa';
  END IF;
END $$;

-- primero las reglas (la columna nueva, 103,5, no cabe en 60), después el dato
ALTER TABLE public.oficina_encargos DROP CONSTRAINT IF EXISTS oficina_encargos_tope_valido;
ALTER TABLE public.oficina_encargos ADD CONSTRAINT oficina_encargos_tope_valido CHECK (tope_usd > 0 AND tope_usd <= 650);
ALTER TABLE public.oficina_tipos_de_grupo DROP CONSTRAINT IF EXISTS oficina_tipos_tope_valido;
ALTER TABLE public.oficina_tipos_de_grupo ADD CONSTRAINT oficina_tipos_tope_valido CHECK (tope_encargo_usd > 0 AND tope_encargo_usd <= 650);

