      pasos = $pasos$[{"clave":"abrir","tipo":"codigo","quien":"sala","funcion":"abrir_video","condicion":{"tipo":"siempre"},"entrada":[],"salida_artefacto":"encargo","tope_usd":0},{"clave":"mesa","tipo":"codigo","quien":"sala","funcion":"mesa","condicion":{"tipo":"siempre"},"entrada":["encargo"],"salida_artefacto":"mesa","tope_usd":0},{"clave":"imagenes_clave","tipo":"codigo","quien":"sala","funcion":"imagenes_clave","condicion":{"tipo":"siempre"},"entrada":["guion","encargo"],"salida_artefacto":"imagenes_clave","tope_usd":0,"tope_usd_por_segundo":0.2},{"clave":"borrador_video","tipo":"codigo","quien":"sala","funcion":"borrador_video","condicion":{"tipo":"siempre"},"entrada":["imagenes_clave"],"salida_artefacto":"borrador_video","tope_usd":0,"tope_usd_por_segundo":0.7},{"clave":"aprobar_propuestas","tipo":"codigo","quien":"sala","funcion":"aprobar_propuestas","condicion":{"tipo":"siempre"},"entrada":["mesa"],"salida_artefacto":"aprobacion_propuestas","tope_usd":0,"vuelve_a":{"paso":"mesa","max":2,"si":{"tipo":"si_artefacto","artefacto":"aprobacion_propuestas","campo":"vuelve_a_la_mesa","igual":true}}},{"clave":"imagenes_clave_final","tipo":"codigo","quien":"sala","funcion":"imagenes_clave","condicion":{"tipo":"siempre"},"entrada":["guion","encargo"],"salida_artefacto":"imagenes_clave_final","tope_usd":0,"tope_usd_por_segundo":0.2},{"clave":"revisar_imagenes_clave","tipo":"agente","quien":"marketing_video_optimization_specialist","condicion":{"tipo":"si_artefacto","artefacto":"imagenes_clave_final","campo":"hay_imagenes","igual":true},"entrada":["imagenes_clave_final","guion"],"salida_artefacto":"revision_imagenes_clave","tope_usd":0.5,"salida":{"esquema":"revision_imagenes_clave.v1","reintento_formato":1},"vuelve_a":{"paso":"mesa","max":1,"si":{"tipo":"si_artefacto","artefacto":"revision_imagenes_clave","campo":"vuelve_a_la_mesa","igual":true}}},{"clave":"pedido","tipo":"codigo","quien":"sala","funcion":"pedido_de_video","condicion":{"tipo":"siempre"},"entrada":["g