UPDATE public.cadena_config SET valor = $brazo${"tope_por_video_usd":60,"tope_por_segundo_usd":2}$brazo$::jsonb, actualizado_en = now() WHERE clave = 'brazo_de_video';

DO $$
BEGIN
  -- la columna = lo calculado a la resolución de la plantilla: 45 + 3,9 × 15 = 103,5
  IF (SELECT (limites->>'tope_encargo_usd')::numeric + (limites->'tope_encargo_usd_por_segundo'->>(limites->'video'->>'resolucion'))::numeric * (limites->'video'->>'segundos_max')::numeric
        FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa')
     IS DISTINCT FROM (SELECT tope_encargo_usd FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa')
     OR (SELECT tope_encargo_usd FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM 103.5::numeric THEN
    RAISE EXCEPTION '202611171900: el dato por segundo no quedó, o no da la columna (103,5)';
  END IF;
  IF (SELECT count(*) FROM pg_constraint WHERE conname IN ('oficina_encargos_tope_valido', 'oficina_tipos_tope_valido') AND pg_get_constraintdef(oid) LIKE '%<= (650)%') IS DISTINCT FROM 2 THEN
    RAISE EXCEPTION '202611171900: las dos reglas no quedaron en 650';
  END IF;
  IF (SELECT valor FROM public.cadena_config WHERE clave = 'brazo_de_video') IS DISTINCT FROM $brazo${"tope_por_video_usd":60,"tope_por_segundo_usd":2}$brazo$::jsonb THEN
    RAISE EXCEPTION '202611171900: la configuración del brazo no quedó';
  END IF;
END $$;

